const bg = scene.querySelector(".bg"), subject = scene.querySelector(".subject");
tl.fromTo(bg, { scale: 1 }, { scale: 1.6, duration: 1.2, ease: "power1.inOut" }, t);
tl.fromTo(subject, { scale: 1 }, { scale: 0.9, duration: 1.2, ease: "power1.inOut" }, t);

const bg = scene.querySelector(".bg"), mid = scene.querySelector(".mid"), fg = scene.querySelector(".fg");
[[bg, 0.2], [mid, 0.5], [fg, 1]].forEach(([layer, k]) =>
  tl.fromTo(layer, { x: 0 }, { x: -300 * k, duration: 1.6, ease: "power1.inOut" }, t));

const W = 1080;
tl.fromTo(a, { x: 0 }, { x: -W, duration: 0.35, ease: "power4.inOut" }, t);
tl.fromTo(b, { x: W }, { x: 0, duration: 0.35, ease: "power4.inOut" }, t);
tl.fromTo([a, b], { filter: "blur(0px)" }, { keyframes: { filter: ["blur(0px)", "blur(30px)", "blur(0px)"] }, duration: 0.35, ease: "none" }, t);

const sceneDur = 5;
tl.fromTo(scene, { x: 0, y: 0, rotation: 0, scale: 1.04 },
  { x: -40, y: -20, rotation: 0.6, scale: 1.04, duration: sceneDur, ease: "none" }, t);

tl.fromTo(scene, { x: 0, y: 0, rotation: 0 }, {
  keyframes: { x: [0, -24, 18, -12, 8, -4, 0], y: [0, 14, -12, 8, -5, 2, 0], rotation: [0, -1.5, 1.2, -0.8, 0.5, -0.2, 0] },
  duration: 0.4, ease: "none" }, t);
tl.fromTo(scene, { filter: "blur(4px)" }, { filter: "blur(0px)", duration: 0.12, ease: "power2.out" }, t);

// origem no rosto/objeto alvo
tl.fromTo(scene, { scale: 1, filter: "blur(0px)", transformOrigin: "50% 38%" },
  { scale: 2.4, filter: "blur(16px)", duration: 0.15, ease: "power4.in" }, t);

// .subject fica dentro de .world: o sujeito anda no mundo e o mundo anda ao contrário (a câmera)
const subject = scene.querySelector(".subject"), world = scene.querySelector(".world");
tl.fromTo(subject, { x: 0 }, { x: 1600, duration: 1.6, ease: "power2.inOut" }, t);
tl.fromTo(world, { x: 0 }, { x: -1400, duration: 1.6, ease: "power2.inOut" }, t + 0.1); // câmera chega depois

const flashEl = scene.querySelector(".flash");
tl.set(scene, { filter: "grayscale(1) contrast(1.2)" }, t);
tl.fromTo(scene, { scale: 1 }, { scale: 1.06, duration: 0.3, ease: "power4.out" }, t);
tl.fromTo(flashEl, { opacity: 0.9 }, { opacity: 0, duration: 0.067, ease: "none", immediateRender: false }, t); // .flash com opacity 0 no CSS

const sceneDur = 6, cycle = 2;
const reps = Math.max(0, Math.floor(sceneDur / cycle) - 1); // loop finito
tl.set(scene, { scale: 1.04 }, t);
tl.fromTo(scene, { x: 0, y: 0, rotation: 0 }, {
  keyframes: { x: [0, 4, -3, 5, -6, 2, 0], y: [0, -3, 4, -2, 3, -4, 0], rotation: [0, 0.3, -0.2, 0.4, -0.3, 0.1, 0] },
  duration: cycle, ease: "none", repeat: reps }, t);

// scene = mundo mais largo que o quadro (worldW px), com o conteúdo espalhado nele
const W = 1080, worldW = 2400;
tl.set(scene, { transformPerspective: 1600 }, t);
tl.fromTo(scene, { x: 0, rotationY: 4 }, { x: -(worldW - W), rotationY: -4, duration: 2.0, ease: "power1.inOut" }, t);

const fg = scene.querySelector(".fg"), bg = scene.querySelector(".bg");
tl.fromTo(fg, { filter: "blur(0px)" }, { filter: "blur(14px)", duration: 0.8, ease: "power2.inOut" }, t);
tl.fromTo(bg, { filter: "blur(14px)" }, { filter: "blur(0px)", duration: 0.8, ease: "power2.inOut" }, t);
tl.fromTo(scene, { scale: 1 }, { scale: 1.02, duration: 0.8, ease: "power2.inOut" }, t); // focus breathing

const occluder = scene.querySelector(".occluder"), stage = scene.querySelector(".stage");
tl.set(occluder, { filter: "blur(12px)" }, t);
tl.fromTo(occluder, { x: 0 }, { x: -1080 * 1.6, duration: 1.2, ease: "power2.inOut" }, t);
tl.fromTo(stage, { x: 0 }, { x: -1080 * 0.4, duration: 1.2, ease: "power2.inOut" }, t);

const inner = gsap.timeline({ paused: true });
inner.fromTo(el, { x: 0, opacity: 1 }, { x: 600, opacity: 1, duration: 1.5, ease: "power2.out" });
tl.fromTo(inner, { progress: 1 }, { progress: 0, duration: 0.6, ease: "power2.in" }, t);
tl.fromTo(scene, { skewX: 0, filter: "blur(0px)" }, {
  keyframes: { skewX: [0, 6, -4, 5, -3, 0], filter: ["blur(0px)", "blur(4px)", "blur(2px)", "blur(4px)", "blur(1px)", "blur(0px)"] },
  duration: 0.6, ease: "none" }, t);

const steps = [1.25, 1.6, 2.0];
tl.set(scene, { scale: 1, transformOrigin: "50% 35%", filter: "blur(0px)" }, t);
steps.forEach((s, k) => {
  tl.set(scene, { scale: s, filter: "blur(3px)" }, t + k * 0.25);
  tl.set(scene, { filter: "blur(0px)" }, t + k * 0.25 + 0.034); // 1 frame a 30 fps
});

// plugin: CustomEase
const inner = gsap.timeline({ paused: true });
inner.fromTo(el, { x: -500, rotation: 0 }, { x: 500, rotation: 360, duration: 1, ease: "none" });
const ramp = CustomEase.create("ramp", "M0,0 C0.2,0.38 0.3,0.47 0.5,0.5 0.7,0.53 0.8,0.62 1,1");
tl.fromTo(inner, { progress: 0 }, { progress: 1, duration: 2.0, ease: ramp }, t);

const base = scene.querySelector(".base"), sharpTop = scene.querySelector(".sharp-top"), sharpBot = scene.querySelector(".sharp-bottom");
tl.fromTo(base, { filter: "blur(0px)" }, { filter: "blur(10px)", duration: 0.6, ease: "power2.out" }, t);
tl.fromTo(sharpTop, { clipPath: "inset(0% 0% 100% 0%)" }, { clipPath: "inset(0% 0% 50% 0%)", duration: 0.6, ease: "power2.out" }, t);
tl.fromTo(sharpBot, { clipPath: "inset(100% 0% 0% 0%)" }, { clipPath: "inset(55% 0% 0% 0%)", duration: 0.6, ease: "power2.out" }, t);

// scene = mundo mais alto que o quadro (worldH px), com o conteúdo espalhado nele
const H = 1920, worldH = 3200;
tl.set(scene, { transformPerspective: 1800, transformOrigin: "50% 0%" }, t);
tl.fromTo(scene, { y: 0, rotationX: 6 }, { y: -(worldH - H), rotationX: -6, duration: 2.0, ease: "sine.inOut" }, t);

const k = 2, px = 820, py = 1300, cx = 540, cy = 960; // alvo em px na cena 1080x1920
tl.fromTo(scene, { scale: 1, x: 0, y: 0, transformOrigin: "50% 50%" },
  { scale: k, x: -(px - cx) * k, y: -(py - cy) * k, duration: 1.0, ease: "power3.inOut" }, t);
